        for j in range(Ww):
            if grid[i][j] in (4,7) and not seen[i][j]:
                col=grid[i][j]; q=deque([(i,j)]); cells=[]; seen[i][j]=True
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<Hh and 0<=y<Ww and not seen[x][y] and grid[x][y]==col:
