def solve2(g):
    H,W=len(g),len(g[0]); cnt=collections.Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; cands=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                col=g[i][j]; q=collections.deque([(i,j)]); seen[i][j]=True; comp=set([(i,j)])
                while q:
                    a,b=q.popleft()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True; q.append((x,y)); comp.add((x,y))
                r0,r1=min(a for a,_ in comp),max(a for a,_ in comp); c0,c1=min(b for _,b in comp),max(b for _,b in comp)
                area=(r1-r0+1)*(c1-c0+1)
                fillfrac=len(comp)/area
                cands.append((fillfrac,area,col,r0,r1,c0,c1))
    res=[list(r) for r in g]
    cands.sort(reverse=True)
    painted=set()
    for fillfrac,area,col,r0,r1,c0,c1 in cands:
        cells=[(a,b) for a in range(r0,r1+1) for b in range(c0,c1+1)]
        for (a,b) in cells:
            if g[a][b]==col: continue
            if (a,b) in painted: continue
            if fillfrac>=0.8 or area>=4*min(r1-r0+1,c1-c0+1):
                res[a][b]=col; painted.add((a,b))
    return res
for key in ['Demo pair 1 input','Demo pair 2 input']:
    pred=solve2(G[key]); exp=G[key.replace('input','output')]
    print(key, pred==exp, [(i,j,pred[i][j],exp[i][j]) for i in range(len(pred)) for j in range(len(pred[0])) if pred[i][j]!=exp[i][j]][:10])

